"use client";
import { FormEvent, useEffect, useState } from "react";
import type { SiteContent, PackageItem } from "../../lib/site-types";
import type { Order, OrderStatus } from "../../lib/orders";
const empty: SiteContent={teacherImage:"",packageImage:"",heroTitle:"",heroHighlight:"",heroDescription:"",teacherTitle:"",teacherDescription:"",phone:"",instagram:"",whatsapp:"",packages:[]};
export default function AdminPage(){
 const [authenticated,setAuthenticated]=useState<boolean|null>(null),[password,setPassword]=useState(""),[content,setContent]=useState<SiteContent>(empty),[message,setMessage]=useState(""),[orders,setOrders]=useState<Order[]>([]);
 const load=async()=>{const [session,data]=await Promise.all([fetch("/api/auth").then(r=>r.json()),fetch("/api/content").then(r=>r.json())]);setAuthenticated(session.authenticated);setContent(data);if(session.authenticated)setOrders(await fetch("/api/orders").then(r=>r.ok?r.json():[]));};useEffect(()=>{load();},[]);
 async function login(e:FormEvent){e.preventDefault();const r=await fetch("/api/auth",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({password})});if(!r.ok)return setMessage("رمز عبور درست نیست.");setAuthenticated(true);setPassword("");await load();}
 async function save(e:FormEvent){e.preventDefault();setMessage("در حال ذخیره...");const r=await fetch("/api/content",{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(content)});setMessage(r.ok?"تغییرات ذخیره شد.":"ذخیره انجام نشد.");}
 async function upload(e:React.ChangeEvent<HTMLInputElement>,key:"teacherImage"|"packageImage"|number,kind:"teacher"|"packages"){const file=e.target.files?.[0];if(!file)return;const form=new FormData();form.append("file",file);form.append("kind",kind);setMessage("در حال آپلود تصویر...");const r=await fetch("/api/upload",{method:"POST",body:form}),data=await r.json();if(!r.ok)return setMessage(data.message||"آپلود انجام نشد.");if(typeof key==="number")setContent(old=>({...old,packages:old.packages.map((p,i)=>i===key?{...p,image:data.path}:p)}));else setContent(old=>({...old,[key]:data.path}));setMessage("تصویر آپلود شد؛ ذخیره همه تغییرات را بزنید.");}
 const update=(key:keyof SiteContent,value:string)=>setContent(old=>({...old,[key]:value}));const editPackage=(i:number,key:keyof PackageItem,value:string)=>setContent(old=>({...old,packages:old.packages.map((p,n)=>n===i?{...p,[key]:value}:p)}));
 async function setStatus(id:string,status:OrderStatus){const r=await fetch("/api/orders",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({id,status})});if(r.ok)setOrders(old=>old.map(x=>x.id===id?{...x,status}:x));}
 if(authenticated===null)return <main className="admin"><p>در حال باز کردن پنل...</p></main>;
 if(!authenticated)return <main className="admin"><section className="adminBox"><h1>مدیریت رایامهر</h1><p>برای ورود، رمز پنل را وارد کنید.</p><form onSubmit={login}><input type="password" value={password} onChange={e=>setPassword(e.target.value)} placeholder="رمز عبور" required/><button>ورود به پنل</button></form>{message&&<p className="error">{message}</p>}</section></main>;
 return <main className="admin"><div className="adminHead"><div><small>پنل مدیریت محتوا</small><h1>ویرایش سایت رایامهر</h1></div><div><a href="/" target="_blank">مشاهده سایت</a><button onClick={async()=>{await fetch("/api/auth",{method:"DELETE"});setAuthenticated(false);}}>خروج</button></div></div><section className="orderList"><h2>سفارش‌ها ({orders.length})</h2>{orders.length?orders.map(o=><article key={o.id}><div><b>{o.parentName}</b><span>{o.phone} · {o.packageName}</span><small>کودک: {o.childName} | {o.childAge}</small></div><select value={o.status} onChange={e=>setStatus(o.id,e.target.value as OrderStatus)}><option value="new">جدید</option><option value="contacted">تماس گرفته شد</option><option value="completed">تکمیل شد</option></select></article>):<p>هنوز سفارشی ثبت نشده است.</p>}</section><form className="editor" onSubmit={save}><section><h2>تصاویر کلی سایت</h2><label>تصویر مدرس<input type="file" accept="image/png,image/jpeg,image/webp" onChange={e=>upload(e,"teacherImage","teacher")}/></label>{content.teacherImage&&<img className="adminPreview" src={content.teacherImage} alt="مدرس"/>}<label>تصویر پیش‌فرض پکیج‌ها<input type="file" accept="image/png,image/jpeg,image/webp" onChange={e=>upload(e,"packageImage","packages")}/></label></section><section><h2>بخش اول صفحه</h2><label>عنوان اصلی<input value={content.heroTitle} onChange={e=>update("heroTitle",e.target.value)}/></label><label>کلمه رنگی<input value={content.heroHighlight} onChange={e=>update("heroHighlight",e.target.value)}/></label><label>توضیح کوتاه<textarea value={content.heroDescription} onChange={e=>update("heroDescription",e.target.value)}/></label></section><section><h2>درباره مدرس</h2><label>عنوان<input value={content.teacherTitle} onChange={e=>update("teacherTitle",e.target.value)}/></label><label>متن معرفی<textarea value={content.teacherDescription} onChange={e=>update("teacherDescription",e.target.value)}/></label></section><section><h2>راه‌های ارتباطی</h2><label>شماره تماس<input value={content.phone} onChange={e=>update("phone",e.target.value)}/></label><label>شناسه اینستاگرام (بدون @)<input value={content.instagram} onChange={e=>update("instagram",e.target.value)}/></label><label>شماره واتساپ با 98<input value={content.whatsapp} onChange={e=>update("whatsapp",e.target.value)}/></label></section><section><h2>پکیج‌ها و تصویر اختصاصی</h2>{content.packages.map((item,i)=><div className="packageEdit" key={i}><label>نام<input value={item.name} onChange={e=>editPackage(i,"name",e.target.value)}/></label><label>بازه سنی<input value={item.age} onChange={e=>editPackage(i,"age",e.target.value)}/></label><label>توضیح<textarea value={item.description} onChange={e=>editPackage(i,"description",e.target.value)}/></label><label>تصویر اختصاصی این پکیج<input type="file" accept="image/png,image/jpeg,image/webp" onChange={e=>upload(e,i,"packages")}/></label>{item.image&&<img className="adminPreview" src={item.image} alt={item.name}/>}</div>)}</section><button className="save">ذخیره همه تغییرات</button>{message&&<p className="status">{message}</p>}</form></main>;
}
